class Gradebook:
    def __init__(self) -> None:
        self.assignments = {}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if name in self.assignments:
            raise ValueError("Assignment already exists")
        if kind not in ["homework", "quiz"]:
            raise ValueError("Invalid kind. Must be 'homework' or 'quiz'")
        self.assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self.assignments:
            raise ValueError("Assignment does not exist")
        if not (2.0 <= grade <= 5.0):
            raise ValueError("Invalid grade. Must be between 2.0 and 5.0")
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if student not in self.grades:
            raise ValueError("Student has no recorded grades")

        # Separate homework and quiz grades
        homework_grades = {assignment: grade for assignment, grade in self.grades[student].items() if self.assignments[assignment]["kind"] == "homework"}
        quiz_grades = {assignment: grade for assignment, grade in self.grades[student].items() if self.assignments[assignment]["kind"] == "quiz"}

        # Drop the lowest quiz grade if there are multiple quizzes
        if len(quiz_grades) > 1:
            lowest_quiz_grade = min(quiz_grades.values())
            quiz_grades = {assignment: grade for assignment, grade in quiz_grades.items() if grade != lowest_quiz_grade}

        # Combine homework and quiz grades
        grades = {**homework_grades, **quiz_grades}

        # Add missing assignments with a grade of 2.0
        for assignment in self.assignments:
            if assignment not in grades:
                grades[assignment] = 2.0

        # Calculate the weighted average
        weighted_sum = sum(grade * self.assignments[assignment]["weight"] for assignment, grade in grades.items())
        total_weight = sum(self.assignments[assignment]["weight"] for assignment in grades)

        # Return the average rounded to two decimal places
        return round(weighted_sum / total_weight, 2)


# Example usage:
